function Initialize-Directory([string]$Path) { if (-not [IO.Directory]::Exists($Path)) { [void][IO.Directory]::CreateDirectory($Path) } }
function Write-Text([string]$Name,[AllowEmptyString()][string]$Text) { if ($Name -eq 'FINAL_STATUS.txt' -and [IO.File]::Exists($EvidenceZip)) { return }; $path = Join-Path $EvidenceRoot $Name; Initialize-Directory ([IO.Path]::GetDirectoryName($path)); [IO.File]::WriteAllText($path,$Text,(New-Object Text.UTF8Encoding($false))) }
function Write-Json([string]$Name,$Value) { Write-Text $Name (($Value | ConvertTo-Json -Depth 30) + [Environment]::NewLine) }
function Get-FileSha256([string]$Path) { $sha = [Security.Cryptography.SHA256]::Create(); $stream = [IO.File]::OpenRead($Path); try { return ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','').ToUpperInvariant() } finally { $stream.Dispose(); $sha.Dispose() } }
function Csv([string]$Name,[object[]]$Rows,[string[]]$Headers) { $lines = New-Object Collections.Generic.List[string]; [void]$lines.Add(($Headers -join ',')); foreach ($row in @($Rows)) { $values = foreach ($header in $Headers) { $value = ''; if ($null -ne $row -and $null -ne $row.PSObject.Properties[$header]) { $value = [string]$row.$header }; '"' + $value.Replace('"','""') + '"' }; [void]$lines.Add(($values -join ',')) }; Write-Text $Name (($lines -join [Environment]::NewLine) + [Environment]::NewLine) }
function Add-Action([string]$Name,[string]$Status,[string]$Detail) { [void]$ActionRows.Add([pscustomobject]@{Time=[DateTimeOffset]::Now.ToString('o');Action=$Name;Status=$Status;Detail=$Detail}) }
function Add-Failure([string]$Class,[string]$Detail) { [void]$FailureRows.Add([pscustomobject]@{Time=[DateTimeOffset]::Now.ToString('o');FailureClass=$Class;Detail=$Detail;Status='ACTIVE'}) }
function Add-Gate([string]$Name,[string]$Status,[string]$Detail) { [void]$GateRows.Add([pscustomobject]@{Gate=$Name;Status=$Status;Detail=$Detail}) }
function Pass-Fail([int]$Code) { if ($Code -eq 0) { return 'PASS' }; return 'BLOCKED' }
function Yes-No([bool]$Value) { if ($Value) { return 'YES' }; return 'NO' }
function Safe-Property($ObjectValue,[string]$Name,$DefaultValue) { if ($null -eq $ObjectValue) { return $DefaultValue }; $property = $ObjectValue.PSObject.Properties[$Name]; if ($null -eq $property) { return $DefaultValue }; return $property.Value }
function Native([string]$Executable,[string[]]$CommandArguments,[string]$Label,[switch]$ComposeProgress) { $errorPath = Join-Path $env:TEMP ('p5r101-' + [guid]::NewGuid().ToString('N') + '.err'); try { $output = @(& $Executable @CommandArguments 2> $errorPath); $exitCode = $LASTEXITCODE; $stdout = ($output | ForEach-Object { [string]$_ }) -join [Environment]::NewLine; $stderr = ''; if ([IO.File]::Exists($errorPath)) { $stderr = [IO.File]::ReadAllText($errorPath) }; Add-Action $Label (Pass-Fail $exitCode) ('ExitCode={0};StdoutBytes={1};StderrBytes={2}' -f $exitCode,$stdout.Length,$stderr.Length); if ($exitCode -ne 0) { throw ('APEX_NATIVE_PROCESS_FAILED:{0}:{1}' -f $Label,$exitCode) }; if ((-not $ComposeProgress) -and $stderr -match '(?i)\b(error|fatal|failed|exception|traceback)\b') { throw ('APEX_NATIVE_STDERR_FAILURE:{0}' -f $Label) }; return [pscustomobject]@{ExitCode=$exitCode;Stdout=$stdout;Stderr=$stderr} } finally { if ([IO.File]::Exists($errorPath)) { Remove-Item -LiteralPath $errorPath -Force -ErrorAction SilentlyContinue } } }
function Inspect-Container([string]$ContainerId,[string]$Label) { $result = Native $Docker @('inspect',$ContainerId) $Label; $rows = @($result.Stdout | ConvertFrom-Json); if ($rows.Count -ne 1) { throw ('APEX_DOCKER_INSPECT_CARDINALITY:{0}:{1}' -f $ContainerId,$rows.Count) }; return $rows[0] }
function Service-Name($Inspect) { $config = Safe-Property $Inspect 'Config' $null; $labels = Safe-Property $config 'Labels' $null; return [string](Safe-Property $labels 'com.docker.compose.service' '') }
function Container-State($Inspect) { $state = Safe-Property $Inspect 'State' $null; return [string](Safe-Property $state 'Status' 'NOT_DEFINED') }
function Network-Names($Inspect) { $settings = Safe-Property $Inspect 'NetworkSettings' $null; $networks = Safe-Property $settings 'Networks' $null; if ($null -eq $networks) { return @() }; return @($networks.PSObject.Properties | Select-Object -ExpandProperty Name) }
function Port-Text($Inspect) { $settings = Safe-Property $Inspect 'NetworkSettings' $null; $ports = Safe-Property $settings 'Ports' $null; if ($null -eq $ports) { return '' }; return ($ports | ConvertTo-Json -Compress -Depth 10) }
function Container-Rows { $result = Native $Docker @('ps','--filter','label=com.docker.compose.project=frappe_docker','--format','{{.ID}}') 'RUNTIME_CENSUS'; $rows = foreach ($containerId in @($result.Stdout -split '\r?\n' | Where-Object { $_.Trim() })) { $inspect = Inspect-Container $containerId ('INSPECT_' + $containerId); $name = [string](Safe-Property $inspect 'Name' ''); $config = Safe-Property $inspect 'Config' $null; [pscustomobject]@{Container=$name.TrimStart('/');Service=(Service-Name $inspect);Image=[string](Safe-Property $config 'Image' '');State=(Container-State $inspect);RestartCount=[int](Safe-Property $inspect 'RestartCount' 0);Networks=((Network-Names $inspect) -join '|');Ports=(Port-Text $inspect)} }; return @($rows) }
function Service-Ids([string]$Service) { $result = Native $Docker @('ps','-aq','--filter',('label=com.docker.compose.service={0}' -f $Service),'--filter','label=com.docker.compose.project=frappe_docker') ('IDS_' + $Service); return @($result.Stdout -split '\r?\n' | Where-Object { $_.Trim() }) }
function Assert-LoopbackBinding([string]$Service,[string]$Port) { $ids = @(Service-Ids $Service); if ($ids.Count -ne 1) { throw ('APEX_PHASE5_CONTAINER_CARDINALITY:{0}:{1}' -f $Service,$ids.Count) }; $inspect = Inspect-Container $ids[0] ('BINDING_' + $Service); $portText = Port-Text $inspect; if ($portText -match '0\.0\.0\.0|\[::\]') { throw ('APEX_PHASE5_PUBLIC_BIND:{0}' -f $Service) }; if ($portText -notmatch ('127\.0\.0\.1.*' + $Port)) { throw ('APEX_PHASE5_LOOPBACK_BIND_MISSING:{0}:{1}' -f $Service,$Port) }; return $inspect }
function Stable-Service([string]$Service,[string]$Port) { $ids = @(Service-Ids $Service); if ($ids.Count -ne 1) { throw ('APEX_PHASE5_CONTAINER_CARDINALITY:{0}:{1}' -f $Service,$ids.Count) }; $inspect = Inspect-Container $ids[0] ('STABILITY_' + $Service); $networks = @(Network-Names $inspect); $image = [string](Safe-Property (Safe-Property $inspect 'Config' $null) 'Image' ''); if ((Container-State $inspect) -ne 'running' -or $image -ne $ExpectedImage -or $networks -notcontains $ExpectedNetwork) { throw ('APEX_PHASE5_RUNTIME_INVALID:{0}' -f $Service) }; if ($Service -eq 'frontend') { [void](Assert-LoopbackBinding $Service ([string]$FrontendPort)) }; if ($Service -eq 'websocket') { [void](Assert-LoopbackBinding $Service ([string]$WebsocketPort)) }; $before = [int](Safe-Property $inspect 'RestartCount' 0); Start-Sleep -Seconds 20; $afterInspect = Inspect-Container $ids[0] ('STABILITY_AFTER_' + $Service); if ((Container-State $afterInspect) -ne 'running' -or [int](Safe-Property $afterInspect 'RestartCount' 0) -ne $before) { throw ('APEX_PHASE5_RESTART_INSTABILITY:{0}' -f $Service) }; return [pscustomobject]@{status='PASS';service=$Service;container=$ids[0];restartCount=$before;stabilitySeconds=20} }
function Compose-Up([string]$Service) { try { [void](Native $Docker @('compose','-p',$ComposeProject,'-f',$ComposeFile,'-f',$OverrideFile,'up','-d','--no-deps',$Service) ('START_' + $Service) -ComposeProgress) } catch { $ids = @(Service-Ids $Service); if ($ids.Count -ne 1) { throw }; $inspect = Inspect-Container $ids[0] ('POSTSTATE_' + $Service); if ((Container-State $inspect) -ne 'running') { throw } } }
function Start-Or-Adopt([string]$Service,[string]$Port) { $ids = @(Service-Ids $Service); if ($ids.Count -eq 1) { $inspect = Inspect-Container $ids[0] ('RESUME_' + $Service); if ((Container-State $inspect) -eq 'running') { try { $stable = Stable-Service $Service $Port; return [pscustomobject]@{action='ADOPTED';startedByRun='NO';runtime=$stable} } catch { } } }; Compose-Up $Service; $stableAfter = Stable-Service $Service $Port; return [pscustomobject]@{action='STARTED_OR_RECOVERED';startedByRun='YES';runtime=$stableAfter} }
function Site-Hashes { $result = Native $Docker @('run','--rm','--network','none','--mount',('type=volume,source={0},target=/sites,readonly' -f $SiteVolume),'--entrypoint','sh',$ExpectedImage,'-c','for p in /sites/frontend/site_config.json /sites/common_site_config.json /sites/apps.txt /sites/apps.json; do sha256sum "$p"; done') 'SITE_HASHES'; $rows = foreach ($line in @($result.Stdout -split '\r?\n' | Where-Object { $_.Trim() })) { $parts = $line -split '\s+',2; if ($parts.Count -ne 2) { throw 'APEX_PHASE5_SITE_HASH_OUTPUT_INVALID' }; [pscustomobject]@{Path=$parts[1];Sha256=$parts[0].ToUpperInvariant()} }; if (@($rows).Count -ne 4) { throw 'APEX_PHASE5_SITE_HASH_COUNT' }; return @($rows) }
function Frappe-Http { $deadline = (Get-Date).AddSeconds(90); $attempts = New-Object Collections.ArrayList; $proof = $null; do { try { $root = Invoke-WebRequest -UseBasicParsing -Uri ('http://127.0.0.1:{0}/' -f $FrontendPort) -Headers @{Host='frontend'} -Method Get -TimeoutSec 10 -ErrorAction Stop; $ping = Invoke-WebRequest -UseBasicParsing -Uri ('http://127.0.0.1:{0}/api/method/ping' -f $FrontendPort) -Headers @{Host='frontend'} -Method Get -TimeoutSec 10 -ErrorAction Stop; $rootStatus = [int]$root.StatusCode; $pingStatus = [int]$ping.StatusCode; $pingContent = [string]$ping.Content; $rootReady = ($rootStatus -eq 200); $pingReady = ($pingStatus -eq 200); $identityReady = ($pingContent.IndexOf('pong',[StringComparison]::OrdinalIgnoreCase) -ge 0); [void]$attempts.Add([pscustomobject]@{RootStatus=$rootStatus;PingStatus=$pingStatus;PingBytes=$pingContent.Length;RootReady=$rootReady;PingReady=$pingReady;IdentityReady=$identityReady}); if ($rootReady) { if ($pingReady) { if ($identityReady) { $proof = [pscustomobject]@{status='PASS';site='frontend';rootStatus=$rootStatus;pingStatus=$pingStatus;responseIdentity='PASS';attempts=@($attempts.ToArray());businessRecordMutation='NO'}; break } } } } catch { [void]$attempts.Add([pscustomobject]@{Error=$_.Exception.Message}) }; Start-Sleep -Seconds 3 } while ((Get-Date) -lt $deadline); if ($null -ne $proof) { return $proof }; $lastAttempt = $null; if ($attempts.Count -gt 0) { $lastAttempt = $attempts[$attempts.Count - 1] }; Write-Json '21_FRONTEND_HTTP_READINESS.json' ([ordered]@{status='BLOCKED';attemptCount=$attempts.Count;lastAttempt=$lastAttempt}); throw 'APEX_PHASE5_FRONTEND_HTTP_READINESS_TIMEOUT' }
function Realtime-Proof { $curl = (Get-Command curl.exe -ErrorAction Stop).Source; $handshake = Native $curl @('-sS','--max-time','10',('http://127.0.0.1:{0}/socket.io/?EIO=4&transport=polling' -f $WebsocketPort)) 'REALTIME_HANDSHAKE'; $content = [string]$handshake.Stdout; $sidMatch = [regex]::Match($content,'"sid"\s*:\s*"([^" ]+)"'); if ($handshake.ExitCode -ne 0 -or $sidMatch.Success -ne $true) { throw 'APEX_PHASE5_REALTIME_HANDSHAKE' }; $sid = $sidMatch.Groups[1].Value; $poll = Native $curl @('-sS','--max-time','35',('http://127.0.0.1:{0}/socket.io/?EIO=4&transport=polling&sid={1}' -f $WebsocketPort,$sid)) 'REALTIME_HEARTBEAT'; if ($poll.ExitCode -ne 0 -or [string]$poll.Stdout -notmatch '(?s)^2') { throw 'APEX_PHASE5_REALTIME_HEARTBEAT' }; return [pscustomobject]@{status='PASS';connection='PASS';protocolHandshake='PASS';heartbeatOrPing='PASS';transport='engine.io-polling';sidRecorded='NO';businessRecordMutation='NO'} }
function Redis-Proof([string]$Service) { $ids = @(Service-Ids $Service); if ($ids.Count -ne 1) { throw ('APEX_PHASE5_CONTAINER_CARDINALITY:{0}' -f $Service) }; [void](Native $Docker @('exec',$ids[0],'getent','hosts','redis-queue') ('REDIS_QUEUE_DNS_' + $Service)); [void](Native $Docker @('exec',$ids[0],'getent','hosts','redis-cache') ('REDIS_CACHE_DNS_' + $Service)); return [pscustomobject]@{status='PASS';service=$Service;redisQueue='redis-queue:6379';redisCache='redis-cache:6379';secretValuesPrinted='NO'} }
function Basic-Service-Proof([string]$Service) { $ids = @(Service-Ids $Service); if ($ids.Count -ne 1) { throw ('APEX_PHASE5_CONTAINER_CARDINALITY:{0}:{1}' -f $Service,$ids.Count) }; $inspect = Inspect-Container $ids[0] ('BASIC_' + $Service); $networks = @(Network-Names $inspect); $before = [int](Safe-Property $inspect 'RestartCount' 0); if ((Container-State $inspect) -ne 'running' -or $networks -notcontains $ExpectedNetwork) { throw ('APEX_PHASE5_PRESERVED_SERVICE_INVALID:{0}' -f $Service) }; Start-Sleep -Seconds 20; $after = Inspect-Container $ids[0] ('BASIC_AFTER_' + $Service); if ((Container-State $after) -ne 'running' -or [int](Safe-Property $after 'RestartCount' 0) -ne $before) { throw ('APEX_PHASE5_PRESERVED_SERVICE_RESTART_INSTABILITY:{0}' -f $Service) }; return [pscustomobject]@{status='PASS';service=$Service;container=$ids[0];image=[string](Safe-Property (Safe-Property $inspect 'Config' $null) 'Image' '');restartCount=$before;stabilitySeconds=20} }
function Initialize-Reports { foreach ($name in $RequiredEvidenceNames) { $path = Join-Path $EvidenceRoot $name; if (-not [IO.File]::Exists($path)) { if ($name.EndsWith('.json')) { Write-Json $name ([ordered]@{status='NOT_STARTED'}) } elseif ($name.EndsWith('.csv')) { Csv $name @([pscustomobject]@{Status='NOT_STARTED'}) @('Status') } else { Write-Text $name 'NOT_STARTED' } } } }
